  auto language=d->findChild<QComboBox*>("raisingFlowLanguage"),background=d->findChild<QComboBox*>("raisingFlowBackground"),choice=d->findChild<QComboBox*>("raisingFlowPreviewScreen");auto tabs=d->findChild<QTabWidget*>("raisingFlowTabs");auto review=d->findChild<QCheckBox*>("raisingFlowReviewed");auto apply=d->findChild<QDialogButtonBox*>("raisingFlowButtons")->button(QDialogButtonBox::Apply);
