  for(int i=0;i<20&&QApplication::focusWidget()!=apply;++i){QVERIFY(QApplication::focusWidget());QTest::keyClick(QApplication::focusWidget(),Qt::Key_Tab);}QCOMPARE(QApplication::focusWidget(),apply);
  // Mouse tab changes and keyboard tab changes both restore the page's first field.
  tabs->setCurrentIndex(0);QTRY_COMPARE(QApplication::focusWidget(),language);QTest::keyClick(QApplication::focusWidget(),Qt::Key_Up);QCOMPARE(language->currentData().toString(),QString("ko"));QVERIFY(!apply->isEnabled());QVERIFY(!review->isChecked());
