  const auto engine=qEnvironmentVariable("RAISING_ENGINE_ROOT",QDir::currentPath());QDir().mkpath(engine+"/.cache/raising-screen-flow");QTemporaryDir dir(engine+"/.cache/raising-flow-shortcuts-XXXXXX");QVERIFY(dir.isValid());QVERIFY(copy(engine+"/examples/my-first-raising-game",dir.path()));QJsonArray assets;
  for(int i=1;i<=2;++i){const auto id="test-image-"+QString::number(i),path="assets/"+id+".png";QImage image(8,8,QImage::Format_RGBA8888);image.fill(i==1?Qt::blue:Qt::red);QVERIFY(image.save(dir.path()+"/"+path));assets.append(QJsonObject{{"id",id},{"kind","image"},{"path",path}});}QVERIFY(write(dir.path()+"/assets/manifest.json",QJsonObject{{"formatVersion","0.1.0"},{"assets",assets}}));
  StudioWindow w(engine);w.resize(1100,700);w.show();w.openProject(dir.path());QTRY_VERIFY_WITH_TIMEOUT(!w.busy()&&!w.projectData().isEmpty(),20000);const auto before=w.projectData();w.findChild<QAction*>("raisingScreenFlow")->trigger();auto d=w.findChild<QDialog*>("raisingScreenFlowDialog");QVERIFY(d);auto tabs=d->findChild<QTabWidget*>("raisingFlowTabs");auto language=d->findChild<QComboBox*>("raisingFlowLanguage"),background=d->findChild<QComboBox*>("raisingFlowBackground"),portrait=d->findChild<QComboBox*>("raisingFlowPortrait");QTRY_COMPARE(QApplication::focusWidget(),language);
